cat > /testbed/test_issue.py << 'EOF'
import numpy as np
import xarray as xr
from xarray.core.indexing import LazilyIndexedArray
from xarray.core.variable import Variable

# Create a custom array wrapper that tracks when __array__ is called
class TrackingArrayWrapper:
    """A wrapper that tracks if the array is loaded"""
    def __init__(self, array):
        self._array = array
        self.loaded = False

    def __array__(self, dtype=None):
        self.loaded = True
        return np.asarray(self._array, dtype=dtype)

    @property
    def shape(self):
        return self._array.shape

    @property
    def dtype(self):
        return self._array.dtype

# Create a lazily indexed array (like what zarr backend creates)
class LazyArray:
    """Simulates a lazy array similar to zarr backing"""
    def __init__(self, shape, dtype):
        self._shape = shape
        self._dtype = dtype
        self.loaded = False

    def __array__(self, dtype=None):
        self.loaded = True
        return np.zeros(self._shape, dtype=dtype or self._dtype)

    @property
    def shape(self):
        return self._shape

    @property
    def dtype(self):
        return self._dtype

# Create a Variable with lazy data
lazy_data = LazyArray((100, 100), np.float64)
var = Variable(dims=('x', 'y'), data=lazy_data)

print("Before accessing chunks:")
print(f"  lazy_data.loaded = {lazy_data.loaded}")

# Create a dataset with this variable
ds = xr.Dataset({'test_var': var})

print("\nAccessing ds.chunks...")
try:
    chunks = ds.chunks
    print(f"  chunks = {chunks}")
except Exception as e:
    print(f"  Error: {e}")

print("\nAfter accessing chunks:")
print(f"  lazy_data.loaded = {lazy_data.loaded}")

if lazy_data.loaded:
    print("\n*** ISSUE REPRODUCED: Accessing chunks loaded the data into memory! ***")
else:
    print("\n*** ISSUE FIXED: Chunks was accessed without loading the data ***")
EOF
python /testbed/test_issue.py

